import{e as r,ab as a,a1 as o,m as i,r as n,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [March]","description":"March 2026 updates","frontmatter":{"title":"Monthly Updates [March]","description":"March 2026 updates","date":"2026-03-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/mar-2026.md","filePath":"posts/mar-2026.md"}'),l={name:"posts/mar-2026.md"};function d(h,e,p,f,m,g){const t=a("Post");return o(),i("div",null,[n(t,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Updated some of the <strong><a href="https://i.ibb.co/7JKx0WJ5/image.png" target="_blank" rel="noreferrer">Homepage Icons</a></strong> / <a href="https://i.imgur.com/8n5Wgw9.png" target="_blank" rel="noreferrer">2</a> to try to make them more clear. Thank you to suprememuhit for doing this.</p></li><li><p>Moved Coding AIs from AI section to Developer Tools with <a href="https://i.ibb.co/mC6MyNQN/image.png" target="_blank" rel="noreferrer">4 new subsections</a> / <a href="https://i.imgur.com/rFZJqJo.png" target="_blank" rel="noreferrer">2</a>. Thank you to anarchydr for doing this.</p></li><li><p>Added new <a href="https://mpv.rocks/" target="_blank" rel="noreferrer">MPV client list</a> site + bumped it to #1 video player as many people feel its the best of the big three (MPV, MPC, VLC.)</p></li><li><p>Added section for <a href="https://fmhy.net/educational#cantonese" target="_blank" rel="noreferrer">Cantonese Learning</a>. Thank you to YEET for doing this.</p></li><li><p>Moved OuterTune from YouTube Music Players to Android Audio Players as they&#39;re <a href="https://github.com/OuterTune/OuterTune/discussions/1116" target="_blank" rel="noreferrer">dropping YTM support</a>.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred both <a href="https://fmhy.net/reading#declassified-leaked-documents" target="_blank" rel="noreferrer">Epstein Exposed + JMail</a> in documents section, we&#39;ve been sent a lot of these, but these 2 seem to have some of the better UIs.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#file-converters" target="_blank" rel="noreferrer">Convert to it!</a> in File Converters, nearly all formats imaginable, file uploads are in browser only, not uploaded to them which is good for privacy.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#file-hosts" target="_blank" rel="noreferrer">ZeroFS</a> in File Hosting, unlimited file size, keeps files for 30 days after its last download.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#unblocked-games" target="_blank" rel="noreferrer">GN-Math</a> in Unblocked Browser Games, has a bunch of good ports, seems to be well liked.</p></li><li><p>Starred <a href="https://fmhy.net/text-tools#font-tools" target="_blank" rel="noreferrer">Font Analyzer</a> in Font Tools, analyses fonts from any page and gives you similar alternatives.</p></li><li><p>Starred <a href="https://fmhy.net/text-tools#pastebins" target="_blank" rel="noreferrer">Markbox</a> (aka fluffle) in Pastebins, alt to rentry with similar UI, has markdown support, editing, etc.</p></li><li><p>Starred <a href="https://fmhy.net/image-tools#image-effects" target="_blank" rel="noreferrer">Efecto</a> in Image Editing, web-based visual effects editor, supports images, videos and 3D models.</p></li><li><p>Starred <a href="https://fmhy.net/ai#video-generation" target="_blank" rel="noreferrer">KLIPY</a> in Video Gen, allows you to generate unlimited GIFs using Veo 3.</p></li><li><p>Starred <a href="https://fmhy.net/image-tools#upscale-restore" target="_blank" rel="noreferrer">Image-Upscaling</a>, online image upscaling tool, works quickly, gives good results.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">Google Flow</a> in Image Gen, gives unlimited Nano Banana Pro / Nano Banana 2.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">Khoj</a> in Image Gen, gives unlimited Nano Banana / Imagen 4.</p></li><li><p>Starred <a href="https://fmhy.net/educational#skills-hobbies-diy" target="_blank" rel="noreferrer">Knots 3D</a> in Educational Skills, 3D interactive guides to learn how to tie any knot.</p></li><li><p>Starred <a href="https://fmhy.net/ai#specialized-chatbots" target="_blank" rel="noreferrer">Google AI Mode</a> in Specialized Chatbots, AI Search Engine, that gives unlimited Gemini 3.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#anti-censorship" target="_blank" rel="noreferrer">Net4People</a> in Censorship Bypass section, worldwide censorship circumvention discussion, chats take place within the GitHub issue section.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#vpn-server" target="_blank" rel="noreferrer">NetBird</a> in VPN Servers, WireGuard Mesh similar to Tailscale, except its open-source, self-hostable, and has a web UI.</p></li><li><p>Starred two <a href="https://fmhy.net/internet-tools#rss-readers" target="_blank" rel="noreferrer">FreshRSS</a> instances in RSS Readers (rss.fmhy + Prodottoinrete), its customizable, web-based, and allows unlimited feeds.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed Duolingo as it has bad privacy, and has gained a rep for being a poor way to learn a language.</p></li><li><p>Removed Pollinations from AI sections as they&#39;re restricting their best models to paid users only now.</p></li></ul>',9))])}const b=r(l,[["render",d]]);export{u as __pageData,b as default};
